# -*- coding: utf-8 -*-
import os, shutil, re
OBS = r"D:\РАБОЧКА\Bekassyl\18_КЖ жүйесі"
def rw(p, f):
    s = open(p, encoding="utf-8").read(); t = f(s); assert t != s, p
    open(p, "w", encoding="utf-8", newline="\n").write(t)
def f00(s):
    a = "| `09_Шаблон для Кж — толық каталог` |"; i = s.index(a); j = s.index("\n", i) + 1
    return s[:j] + "| `10_Шаблоннан алынатын тұрақты блоктар (өзің жасама)` | Ведомость деталей, спецификация, расход стали, узелдер, примечание, штамп — қай блок шаблонның қай парағынан клондалады; өзің сызуға тыйым | әр парақты жасар алдында |\n" + s[j:]
rw(os.path.join(OBS, "00_ОҚЫ_АЛДЫМЕН — КЖ жүйесі (АР + ЛИРА → толық альбом).md"), f00)
def f02(s):
    a = "- Алдымен **бір пилот парақ**:"; assert a in s
    return s.replace(a, "- **Тұрақты блоктар тек шаблоннан (не берілген аналогтан) клондалады:** ведомость деталей (эскиздерімен), спецификация, ведомость расхода стали, ведомость чертежей, стык/анкеровка/накладка узелдері, сетка, примечание мәтіндері, штамп. Ішіндегі сан мен мәтін ғана ауыстырылады; кестені, эскизді, примечаниені өзің сызба/жазба. Қай блок қайдан — `18_КЖ жүйесі\\10_Шаблоннан алынатын тұрақты блоктар`. Өз ойыңнан тек схема мен элемент геометриясы (заданиеден, аналог құрылымымен). Шаблонда жоқ блок керек болса — сұрақтарға жаз.\n" + a, 1)
rw(os.path.join(OBS, "02_ПРОМПТТАР тізбегі (П0–П10).md"), f02)
def f03(s):
    L = s.split("\n"); k = [i for i, l in enumerate(L) if l.startswith("| А14 |")][0]
    L.insert(k + 1, "| А15 | Тұрақты блоктар (ведомость деталей мен эскиздері, спецификация, расход стали, узелдер, примечание, штамп) шаблон/аналог блогының клоны: бағандары, эскиз пішіні, «по в.г./по н.г.», мәтіні шаблондағыдай; өзің сызған кесте не эскиз жоқ (`10` файлы) | блок/стиль аты + шаблон парағымен қатар салыстыру |")
    return "\n".join(L)
rw(os.path.join(OBS, "03_Армирование — қатаң чек-лист.md"), f03)
RULE = ("- **ТҰРАҚТЫ БЛОКТАР ШАБЛОННАН (13.11):** ведомость деталей (эскиздерімен), спецификация, ведомость расхода стали, ведомость чертежей, типтік узелдер (стык, анкеровка, накладка, сетка), примечание, штамп — тек `Шаблон для Кж.dwg`-ден (не берілген аналогтан) клондалады, ішіндегі сан мен мәтін ғана ауыстырылады; өзің сызба. "
        "Өз жұмысың — тек заданиеден шығатын схема мен элемент геометриясы, аналог құрылымымен. Қай блок қайдан: Obsidian `18_КЖ жүйесі\\10_Шаблоннан алынатын тұрақты блоктар`.\n")
ANCH = "- Кез келген жұмыс алдында Obsidian-ды оқы:"
for p in (r"C:\Users\Admin\.claude\CLAUDE.md", r"D:\РАБОЧКА\.claude\CLAUDE.global.md"):
    s = open(p, encoding="utf-8").read(); assert ANCH in s
    if "ТҰРАҚТЫ БЛОКТАР ШАБЛОННАН" not in s: open(p, "w", encoding="utf-8", newline="\n").write(s.replace(ANCH, RULE + ANCH, 1))
m = r"C:\Users\Admin\.claude\projects\D---------\memory"
open(os.path.join(m, "constant-blocks-from-template.md"), "w", encoding="utf-8", newline="\n").write("""---
name: constant-blocks-from-template
description: Тұрақты блоктар (ведомость деталей, спецификация, расход, узелдер, примечание, штамп) тек шаблоннан/аналогтан клондалады; өз ойымнан тек схема мен геометрия (13.11.2026)
metadata:
  type: feedback
---

КЖ парағындағы тұрақты нәрселерді — ведомость деталей (эскиздерімен), спецификация элементов, ведомость расхода стали, ведомость чертежей, стык/анкеровка/накладка/сетка узелдері, примечание мәтіндері, штамп — өзім сызбаймын: `D:\\РАБОЧКА\\Шаблон для Кж.dwg`-ден (не берілген аналогтан) клондап, ішіндегі сан мен мәтінді ғана ауыстырамын. Өз жұмысым — тек заданиеден (АР, ТХ, ЛИРА) шығатын схема мен элемент геометриясы, аналог парағының құрылымымен.

**Why:** пайдаланушы 13.11.2026, Отстойники парақтарын көріп: «Ведомость деталей бар ғой, соны өзі жасаған; оны өзі жасамасын, менің берген аналогымнан алсын… Ештеңені ойдан ойлап таппасын. Ведомость, спецификация деген сияқты тұрақты болатын заттардың барлығын шаблоннан алсын. Ал зданияның тек өзгерісі, схемасы — соны ғана аналог бойынша. Өз ойынан ешкім ештеңе жасамасын».

**How to apply:** қай блок шаблонның қай парағында — Obsidian `18_КЖ жүйесі\\10_Шаблоннан алынатын тұрақты блоктар (өзің жасама).md` (ведомость деталей эскиздері: M_11, M_13, M_15, X2 кітапханасы; хомут/шпилька «по в.г.», скоба/фиксатор «по н.г.»). Шаблонда жоқ блок керек болса — тоқта, сұра. Тексеріс: чек-лист А15 (блок шаблон клоны ма, шаблон парағымен қатар салыстыру). Отстойники бес объектісінде ведомость деталей қайта клондалуы керек (сол жобаның сессиясында). Байланысты: [[kzh-system-ar-lira-album]], [[vedomost-detaley-all-positions]], [[drawing-copy-not-create]], [[analog-first-then-github-then-ask]], [[project-otstoiniki-make]].
""")
p = os.path.join(m, "MEMORY.md"); s = open(p, encoding="utf-8").read()
a = "- [МІНДЕТТІ: алдымен Obsidian]"
if "constant-blocks-from-template" not in s:
    open(p, "w", encoding="utf-8", newline="\n").write(s.replace(a, "- [МІНДЕТТІ: тұрақты блоктар шаблоннан](constant-blocks-from-template.md) — ведомость деталей, спецификация, узел, примечание клондалады; өзім тек схема\n" + a, 1))
p = os.path.join(m, "project-otstoiniki-make.md"); s = open(p, encoding="utf-8").read()
if "13.11.2026" not in s:
    open(p, "w", encoding="utf-8", newline="\n").write(s.rstrip("\n") + "\n\n**13.11.2026 (пайдаланушы парақтарды көрді):** «біраз қате бар»; нақты атағаны — ведомость деталей өз бетімен сызылған, шаблон/аналогтан алынбаған. Түзету: [[constant-blocks-from-template]] бойынша ведомость деталей, спецификация, расход, примечание шаблон блоктарынан қайта клондалсын; қалған қателер парақтарды `18_КЖ жүйесі\\10` тізімімен салыстырғанда анықталады.\n")
std = r"D:\Бекасыл КЖ КМ\_Стандарт_КЖ"
if not os.path.isdir(os.path.join(std, "КЖ_жүйесі")): std = os.path.join(os.environ["LOCALAPPDATA"], "bekassyl-std", "_Стандарт_КЖ")
dst = os.path.join(std, "КЖ_жүйесі")
for f in os.listdir(OBS):
    sp = os.path.join(OBS, f)
    if os.path.isdir(sp): shutil.copytree(sp, os.path.join(dst, f), dirs_exist_ok=True)
    else: shutil.copyfile(sp, os.path.join(dst, f))
p = os.path.join(std, "ЕРЕЖЕЛЕР.md"); s = open(p, encoding="utf-8").read()
last = max(int(x) for x in re.findall(r"  - №(\d+) \(", s)); i = s.index("  - №%d (" % last); j = s.index("\n", i) + 1
open(p, "w", encoding="utf-8", newline="\n").write(s[:j] + "  - №%d (13.11, пайдаланушы, Отстойники — тұрақты блоктар шаблоннан): «Ведомость деталей бар ғой, соны өзі жасаған; оны өзі жасамасын, менің берген аналогымнан алсын… Ведомость, спецификация деген сияқты тұрақты болатын заттардың барлығын шаблоннан алсын. Ал зданияның тек өзгерісі, схемасы — соны ғана аналог бойынша. Өз ойынан ешкім ештеңе жасамасын». Тұрақты блоктар (ведомость деталей эскиздерімен, спецификация, ведомость расхода стали, ведомость чертежей, стык/анкеровка/накладка/сетка узелдері, примечание, штамп) тек `Шаблон для Кж.dwg`-ден не берілген аналогтан клондалады, сан мен мәтін ғана ауыстырылады. Қай блок қайдан: `КЖ_жүйесі\\10_Шаблоннан алынатын тұрақты блоктар`. Тексеріс: чек-лист А15.\n" % (last + 1) + s[j:])
print("ok", last + 1, std)
